            "de": "Das Wahrzeichen von Trier ist die berühmte Porta Nigra, das am besten erhaltene römische Stadttor nördlich der Alpen.",
            "ar": "المَعلم الأبرز لمدينة ترير هو بوابة بورتا نيجرا (البوابة السوداء) الشهيرة، وهي أفضل بوابة مدينة رومانية محفوظة شمال جبال الألب.",
