            "de": "Einerseits waren es oft Kaufleute, die zum Verkauf ihrer Waren andere Orte besuchen mussten. Andererseits reisten Menschen aus religiösen Gründen.",
            "ar": "فمن ناحية، كان معظمهم من التجار الذين يضطرون لزيارة مناطق أخرى لبيع بضائعهم، ومن ناحية أخرى كان السفر لأسباب دينية (حج).",
