            "id": "text-09-p1-s2",
            "de": "Nur leider habe ich dann kein Zimmer gefunden. Aber das Semester hat angefangen und irgendwo musste ich ja übernachten. Also habe ich mich entschieden, erst mal im Zug zu wohnen.",
            "ar": "ولكن للأسف لم أجد غرفة للسكن، وبدأ الفصل الدراسي وكان لا بد أن أبيت في مكان ما؛ فقررت أن أعيش مؤقتاً في القطار!",
