            "id": "text-09-p2-s1",
            "de": "„Ich bin jetzt seit 9 Jahren auf Reisen. Ursprünglich wollte ich mir nach meiner Ausbildung nur für ein Jahr eine Auszeit nehmen und ein bisschen was von der Welt sehen.",
