      {
        "id": "ex-10-01",
        "type": "فهم المسؤوليات (Buch S. 58)",
        "prompt": "Warum warnt Stefan Kampmann davor, den Notruf 112 für Auskünfte wie offene Apotheken zu nutzen?",
        "options": [
          {
            "text": "Weil die Notrufleitung für lebensbedrohliche Notfälle frei bleiben muss und das Blockieren strafbar sein kann."
          },
          {
            "text": "Weil die Feuerwehr nachts keine Telefone bedient."
          },
          {
            "text": "Weil Apotheken in Deutschland nachts immer geschlossen sind."
          }
        ],
        "correctIndex": 0,
        "explanation": "خط الطوارئ 112 مخصص حصراً للحرائق والحوادث الخطيرة وإنقاذ الأرواح، وإشغاله باستفسارات بسيطة يعرض حياة الآخرين للخطر ويعاقب عليه القانون."
      }
